use vstd::prelude::*;

verus! {

fn r_(a: Vec<i8>, b: Vec<i8>) -> (res: Vec<i8>)
    ensures
        res@.len() == a@.len() + b@.len(),
        forall|i: int| 0 <= i < a@.len() ==> res@[i] == a@[i],
        forall|j: int| 0 <= j < b@.len() ==> res@[a@.len() + j] == b@[j],
{
    let a_len: usize = a.len();
    let b_len: usize = b.len();

    let mut out: Vec<i8> = Vec::new();
    out.reserve(a_len + b_len);

    let mut i: usize = 0;
    while i < a_len
        invariant
            out@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> out@[k] == a@[k],
            a_len == a.len(),
            b_len == b.len(),
        decreases a_len - i,
    {
        out.push(a[i]);
        i += 1;
    }

    let mut j: usize = 0;
    while j < b_len
        invariant
            out@.len() == a_len as int + j as int,
            // First part matches a completely
            forall|k: int| 0 <= k < a_len as int ==> out@[k] == a@[k],
            // Second part matches b for what we've appended so far
            forall|k: int| 0 <= k < j as int ==> out@[a_len as int + k] == b@[k],
            a_len == a.len(),
            b_len == b.len(),
        decreases b_len - j,
    {
        out.push(b[j]);
        j += 1;
    }

    out
}

} // verus!

